# coding: utf-8
from lesson_authoring import entry as E
B=[['希腊 aer，属格 aeros','空气'],['拉丁 aer → 法语 air → 英语 air','空气']]
W=[
E('air','英 /eə/；美 /er/','空气；天空；通风；公开表达；播出','本来是围在身边、看不见却能呼吸的东西；让东西接触空气，就有通风、公开的感觉。','空气义经法语 air、拉丁 aer 接希腊 aer；现代 air 本身已不能再拆成有意义的英语小块。',B+[['英语 air 的动词及广播用法','让空气接触 → 通风；把意见说出来；通过无线电播出']],'fresh air 是新鲜空气；air the room 是通风；air concerns 是把担忧公开讲出来；on air 是正在播出。an air of mystery 的神秘气质、put on airs 的摆架子还涉及法语表示神态的另一历史用法，远源有争议，别硬说所有义项都由空气一条线变来。','fresh air；in the air；air an opinion；on air；up in the air〔尚未确定〕。','air 和 heir 继承人同音。air concerns 是表达担忧，不是让担忧消失；clear the air 才常比喻消除误会、把话说开。',('Open the window and let some fresh air in.','打开窗户，让新鲜空气进来。'),('The meeting gave everyone a chance to air their concerns.','会议让每个人都有机会说出自己的担忧。'),('The interview will air on Sunday evening.','这段访谈将在周日晚间播出。'),sources=['https://www.etymonline.com/word/air','https://en.wiktionary.org/wiki/air']),
E('airy','英 /ˈeəri/；美 /ˈeri/','通风宽敞的；轻盈的；轻飘飘、不当回事的','像屋里留了很多空气，感觉开阔轻松；也可能轻到没有分量。','air + -y；从有空气、通风，扩展到轻盈或轻率。',B+[['air + -y → airy','有空气感的 → 宽敞、轻盈；轻率']],'an airy room 是通风、开阔的房间；an airy dress 可以说裙子轻薄飘逸；an airy dismissal 常含批评，说对方轻描淡写地把问题打发了。','a light and airy room；an airy space；an airy manner；an airy dismissal。','airy 用在房间上常是夸奖，用在承诺或态度上却可能说太轻浮、不认真。不能统一翻成空气多。',('The apartment is bright and airy.','这套公寓明亮又通透。'),('His airy dismissal of the problem annoyed the team.','他对问题那种轻描淡写的态度惹恼了团队。'),sources=['https://www.etymonline.com/word/airy','https://en.wiktionary.org/wiki/airy']),
E('airiness','英 /ˈeərinəs/；美 /ˈerinəs/','通透宽敞感；轻盈感；漫不经心的态度','把 airy 描写出的感觉拿出来说：这间屋为什么让人不憋闷，这个人为什么显得太轻松。','airy 将 y 改为 i，再加 -ness；表示性质或状态。',B+[['airy → airiness','通透、轻盈的 → 通透感、轻盈感']],'the airiness of the room 是房间的通透感；the airiness of her reply 则可能指回答得太随意。建筑、衣料、声音都能有轻盈感，但每个场景的中文不必用同一个词。','a sense of airiness；the airiness of a room；an airiness of manner。','airiness 不等于实际空气体积。说设计营造 airiness，往往是在说视觉与空间感。',('The pale walls add to the room’s airiness.','浅色墙面让房间显得更通透。'),('There was an airiness in his reply that made her doubt his commitment.','他回答得有些漫不经心，让她怀疑他是否真会投入。'),sources=['https://en.wiktionary.org/wiki/airiness','https://dictionary.cambridge.org/pronunciation/english/airiness']),
E('airless','英 /ˈeələs/；美 /ˈerləs/','没有空气的；闷热不通风的','空气好像不流动，人一走进去就觉得闷。','air + -less，没有空气或缺少空气流通。',B+[['air + -less → airless','无空气的 → 不通风、令人憋闷的']],'an airless room 在普通描述里通常不是物理上的真空，而是空气不流通、令人憋闷。an airless world 在太空话题中才可能真正说没有大气。','an airless room；an airless office；an airless planet。','stuffy 和 airless 都能形容闷；airless 有时还用于文学比喻，形容封闭到缺乏活力的环境。',('We waited in a small, airless room.','我们在一间又小又不通风的房间里等着。'),('The novel creates an airless atmosphere of suspicion.','小说营造出一种猜忌重重、令人窒息的氛围。'),sources=['https://en.wiktionary.org/wiki/airless','https://www.oxfordlearnersdictionaries.com/definition/english/airless']),
E('airflow','英 /ˈeəfləʊ/；美 /ˈerfloʊ/','气流；空气流动','不只是屋里有没有空气，而是空气沿哪条路、以多大流量流动。','英语 air + flow 流动；从流体运动的画面理解即可。',B+[['air + flow → airflow','空气的流动']],'improve airflow 是让空气更顺畅地通过；block airflow 是挡住气流。电脑散热、房间通风和汽车设计都能用到这个词。','improve airflow；restrict airflow；airflow through a space；airflow around a wing。','air 是物质，airflow 是它的运动。一个密闭空间里有空气，也可能几乎没有有效的空气流动。',('The new vents improve airflow through the room.','新通风口改善了房间里的空气流动。'),('Dust can restrict airflow inside a computer.','灰尘可能阻碍电脑内部的气流。'),sources=['https://en.wiktionary.org/wiki/airflow','https://www.oxfordlearnersdictionaries.com/definition/english/airflow']),
E('airtight','英 /ˈeətaɪt/；美 /ˈertaɪt/','密不透气的；严密无漏洞的','像盖子扣得严丝合缝，连空气都钻不进去；再比喻理由也找不出缝隙。','air + tight 严密的；tight 在这里不是紧张或时间紧。',B+[['air + tight → airtight','空气通不过的 → 论证严密的']],'an airtight container 是密封容器；an airtight argument 是严密的论证；an airtight alibi 是看起来无懈可击的不在场证明。比喻义抓住的是“漏洞进不来”。','an airtight container；an airtight seal；an airtight argument；an airtight alibi。','airtight 说封闭严密，airless 说缺空气或不通风。容器可以密封但里面仍装着空气。',('Store the biscuits in an airtight container.','把饼干放在密封容器里保存。'),('Her argument seemed airtight until a new fact emerged.','在新事实出现之前，她的论证看起来无懈可击。'),sources=['https://en.wiktionary.org/wiki/airtight','https://www.oxfordlearnersdictionaries.com/definition/english/airtight']),
E('airborne','英 /ˈeəbɔːn/；美 /ˈerbɔrn/','在空中的；由空气传播的；空运的','borne 是被承载：东西离了地，由空气或飞行器带着走。','air + borne；borne 是 bear 承载的过去分词，不是 born 出生。',B+[['air + borne → airborne','被空气承载的 → 在空中或通过空气传播']],'The plane is airborne 说飞机已经离地；airborne dust 是飘在空气中的灰尘；airborne troops 指通过航空方式投入行动的部队。具体是悬浮、传播还是运输，要看名词。','become airborne；airborne dust；airborne particles；airborne troops。','airborne 不表示所有东西都靠翅膀主动飞。灰尘被气流带着，也是 airborne。',('The plane was airborne within a minute.','不到一分钟，飞机就已经升空了。'),('The filter captures airborne dust.','过滤器会捕捉空气中悬浮的灰尘。'),sources=['https://en.wiktionary.org/wiki/airborne','https://www.oxfordlearnersdictionaries.com/definition/english/airborne']),
E('aerial','英 /ˈeəriəl/；美 /ˈeriəl/','空中的；从空中进行的；天线','把观察位置移到空中：俯瞰地面，或者让信号经空中传来。','希腊 aerios → 拉丁 aerius，再接 -al；天线名词义由 aerial antenna 一类表达缩短而来。',B[:1]+[['希腊 aerios → 拉丁 aerius → aerial','空气相关、在空中的'],['aerial antenna → aerial〔名词〕','空中天线 → 天线']],'an aerial photograph 是航拍照片；an aerial view 是鸟瞰图。英国英语里的 TV aerial 是电视天线，对应常用的 antenna。词尾 -ial 只表示相关性质，不是 air 加 real。','an aerial view；aerial photography；aerial footage；a television aerial。','aerial 说空中视角或相关事物，airy 常说通透轻盈。an aerial room 不是 airy room 的替代。',('The report includes aerial photographs of the coast.','报告中有海岸的航拍照片。'),('The old television had a small aerial on top.','那台旧电视顶部装着一根小天线。'),sources=['https://www.etymonline.com/word/aerial','https://en.wiktionary.org/wiki/aerial'])
]
